  "plans.priceNote": "Essentials مبلغ $14.99/ماه به علاوه مالیه‌های قابل اجرا، در صورت وجود، است. Business مبلغ $29.99/ماه به علاوه مالیه‌های قابل اجرا، در صورت وجود، است. هر مالیه لازم در جریان پرداخت ارائه‌دهنده تعیین می‌شود و باید در مجموع نهایی قبل از پرداخت ظاهر شود. این صفحه مقایسه یک نقل‌قول مالیه یا اجازه پرداخت نیست.",
  "plans.mobilePriceNote": "پلان صرفاً موبایل $4.99/ماه با قیمت پایه مورد نظر آن در ایالات متحده است. App Store یا Google Play قیمت واقعی اشتراک محلی و هر مالیه قابل اجرا را قبل از خرید نشان می‌دهد. سهمیه‌های محصول، سایت و کارمندان آن هنگام عرضه، جدا از رده‌های وب‌سایت، تعیین می‌شوند.",
