  "upgrade.trialHistoryNote": "اگر برای Essentials پرداخت می‌کنید و به Business می‌روید، همان حساب مشتری و سابقه دوره آزمایشی را نگه می‌دارید. Business یک دوره آزمایشی هفت‌روزه اضافی را شامل نمی‌شود. اگر در حالی که دوره آزمایشی اصلی شما هنوز در جریان است ارتقا دهید، تاریخ پایان اصلی آن از نو تنظیم نمی‌شود.",
  "upgrade.providerConfirmNote": "تغییرات پلان نیاز به تأیید از ارائه‌دهنده صورت‌حساب دارند. هر تفاوت قیمت، تناسب‌بندی و تاریخ اجرا باید قبل از تأیید تغییر نشان داده شود. یک ارتقا نباید اشتراک همزمان دوم بسازد.",
  "upgrade.chargedThroughProviderNote": "تغییرات پلان از طریق ارائه‌دهنده صورت‌حساب شارژ می‌شوند. شما می‌توانید اشتراک خود را از این صفحه با استفاده از دکمه لغو اشتراک در زیر پلان فعلی خود، یا از تنظیمات، لغو کنید. لغو تمدیدهای آینده را در پایان دوره پرداخت‌شده شما متوقف می‌کند؛ هرگز دسترسی شما را یکباره پایان نمی‌دهد. محیط‌های کاری رایگان موجود با دیدن این گزینه‌ها شارژ نمی‌شوند.",
