  "print.howToReach": "چگونه به چاپگر خود برسید",
  "print.howIntro": "این برنامه به چاپگرهایی که قبلاً دارید وصل می‌شود — خودش یک چاپگر نیست. چهار راه برای رسیدن به یکی وجود دارد و برچسب‌ها روی هر دو پلان از طریق هر کدام چاپ می‌شوند. برگه‌های بسته‌بندی، سفارشات خرید، اسناد تأمین‌کننده و گزارش‌ها صرفاً Business هستند، هر اتصالی که باشد.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "از این صفحه، در Chrome یا Edge دسکتاپ و در Chrome اندروید: چاپگر برچسب خود را انتخاب کنید و برچسب‌ها مستقیم به آن می‌روند. در Safari آیفون کار نمی‌کند — در آیفون، چاپ Bluetooth همراه با برنامه موبایل می‌آید. چاپگری که فقط به زبان Zebra ZPL یا زبان خود Brother صحبت می‌کند برچسب‌هایی را که این صفحه می‌فرستد نمی‌فهمد؛ این در برابر چاپگرهای واقعی بررسی می‌شود قبل از اینکه کارکرده نامیده شود.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "چاپگر را روی Wi-Fi دکان خود نصب کنید، سپس از دکمه چاپ استفاده کنید — از طریق چاپگر نصب‌شده روی این کمپیوتر، از طریق شبکه دکان، چاپ می‌کند. در آیفون، AirPrint داخلی است: یک چاپگر AirPrint روی همان Wi-Fi فقط در ورق چاپ ظاهر می‌شود، بدون سیم و بدون برنامه لازم، و برنامه به هیچ کود خاص AirPrint نیاز ندارد. چاپگر باید از AirPrint پشتیبانی کند (بیشتر چاپگرهای جدید می‌کنند) و تلفن و چاپگر باید روی همان Wi-Fi باشند.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "چاپگر را با یک سیم Ethernet به شبکه دکان خود وصل کنید، آن را روی کمپیوتر نصب کنید و از طریق دکمه چاپ چاپ کنید. Ethernet یک مسیر دسکتاپ و کمپیوتر است — آیفون‌ها از سیم‌های Ethernet استفاده نمی‌کنند.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "چاپگر را با سیم آن به کمپیوتر وصل کنید و از دکمه چاپ استفاده کنید — از طریق چاپگر نصب‌شده در آنجا چاپ می‌کند. در یک تلفن اندروید با یک کیبل USB OTG، دکمه USB در بالا مستقیم با چاپگر صحبت می‌کند. آیفون‌ها نمی‌توانند مستقیم از طریق USB چاپ کنند — هیچ WebUSB در آنجا نیست — پس از Wi-Fi / AirPrint استفاده کنید، یا از برنامه موبایل از Bluetooth استفاده کنید.",
  "print.howCordsLead": "سیم‌ها هنوز به آیفون‌ها خدمت می‌کنند، یک قدم دورتر.",
  "print.howCordsBody": "یک چاپگر USB وصل‌شده به کمپیوتر دکان، یا یک چاپگر Ethernet وصل‌شده به شبکه، روی آیفون شما از طریق Wi-Fi دکان ظاهر می‌شود (AirPrint / چاپگر شریک) — سیم‌ها چاپگر را به طور محکم روی شبکه می‌گذارند و تلفن به طور بی‌سیم به آن می‌رسد.",
  "print.howOfflineLead": "اگر اینترنت قطع شود،",
  "print.howOfflineBody": "برچسب‌ها و اسنادی که قبلاً روی این صفحه هستند هنوز چاپ می‌شوند — دکمه چاپ، PDF برچسب‌ها، Bluetooth و USB به هیچ اتصالی نیاز ندارند. آنچه به اینترنت نیاز دارد بار کردن صفحه و محصولات آن در وهله اول است. حالت کامل آفلاین (کار کردن در برنامه بدون هیچ اتصالی) یک ساخت جدا و بزرگ‌تر است و در اینجا ادعا نمی‌شود.",
