  "rewards.voided": "پاداش باطل شد.",
  "workforce.tab.rewards": "پاداش‌ها",
  "training.lessons.mgr-give-rewards.step1": "نیروی کار را باز کنید و پاداش‌ها را بزنید. عضو تیم را انتخاب کنید، سپس نوع را: یک فیصدی تخفیف در دکان، یک کارت تحفه، یا چیز دیگری که با کلمات خودتان توصیف می‌کنید.",
  "training.lessons.mgr-give-rewards.step2": "به پاداش یک نام کوتاه بدهید و اگر دوست دارید یک یادداشت. آن شخص فوراً یک زنگ دریافت می‌کند، و پاداش در پاداش‌های من او با کود خودش منتظر می‌ماند.",
  "training.lessons.mgr-give-rewards.step3": "مرز، بر اساس طراحی: شما فقط به کارمندان پاداش می‌دهید. شما نمی‌توانید به خودتان یا یک مدیر دیگر پاداش دهید — پاداش دادن به یک مدیر تصمیم مالک است، و برنامه آن را به روشنی رد می‌کند.",
  "training.lessons.mgr-give-rewards.step4": "در صندوق، کودی را که عضو تیم به شما نشان می‌دهد تایپ کنید و آن را استفاده‌شده علامت بزنید — هر کود یک بار کار می‌کند. شما می‌توانید پاداشی را که دادید اگر پلان‌ها تغییر کردند باطل کنید؛ تحفه‌های مالک از آن مالک هستند که باطل کند.",
  "training.lessons.mgr-give-rewards.title": "دادن پاداش به کارمندان شما",
  "training.lessons.owner-give-rewards.step1": "پاداش‌ها در نیروی کار زندگی می‌کنند، در زبانه پاداش‌ها، و آن‌ها فقط برای پلان Business هستند — در Essentials زبانه یک دروازه قفل‌شده نشان می‌دهد، تا تیم شما بتواند ببیند پلان بزرگ‌تر چه دارد.",
  "training.lessons.owner-give-rewards.step2": "شما می‌توانید به هر کسی در تیم پاداش دهید — کارمندان و مدیران به یکسان. شخص را انتخاب کنید، سپس نوع را: یک فیصدی تخفیف در دکان (هر فیصدی که انتخاب می‌کنید)، یک کارت تحفه به هر جا، یا هر انگیزه‌ای که با کلمات خودتان توصیف می‌کنید.",
  "training.lessons.owner-give-rewards.step3": "پاداش با کود یک‌بارمصرف خودش می‌نشیند و زنگ آن شخص را به صدا درمی‌آورد. آن‌ها کود را در صندوق نشان می‌دهند؛ یک مالک یا مدیر آن را تایپ می‌کند تا استفاده‌شده علامت بخورد.",
  "training.lessons.owner-give-rewards.step4": "یک برگه پاداش چاپ‌شده یا شریک‌شده فقط نام تجارت شما را دارد — هرگز نام برنامه را نه. آن تشکر دکان شماست، نه یک اعلان.",
  "training.lessons.owner-give-rewards.title": "دادن پاداش‌ها (پلان Business)",
  "training.lessons.owner-rewards-oversight.step1": "مدیر شما نیز می‌تواند پاداش بدهد — فقط به کارمندان. برنامه یک مدیر را که به خودش یا یک مدیر دیگر پاداش می‌دهد رد می‌کند؛ پاداش دادن به یک مدیر همیشه تصمیم شماست.",
  "training.lessons.owner-rewards-oversight.step2": "شما هر پاداش را در تجارت در تاریخچه پاداش می‌بینید: چه کسی آن را داد، چه کسی آن را گرفت، و آیا آماده، استفاده‌شده یا باطل است. یک مدیر فقط پاداش‌هایی را می‌بیند که داده است و آن‌هایی را که دریافت کرده است.",
  "training.lessons.owner-rewards-oversight.step3": "شما می‌توانید هر پاداشی را باطل کنید، بشمول یکی که مدیر شما داده است. یک مدیر می‌تواند تحفه‌های خودش را باطل کند، اما هرگز مال شما را نه.",
  "training.lessons.owner-rewards-oversight.step4": "هر کود دقیقاً یک بار کار می‌کند، و یک پاداش باطل‌شده هرگز استفاده نمی‌شود — تاریخچه همیشه نشان می‌دهد یک پاداش چگونه پایان یافت.",
  "training.lessons.owner-rewards-oversight.title": "نظارت بر پاداش‌ها: دادن مدیر شما",
  "training.lessons.staff-your-rewards.step1": "وقتی مدیر یا مالک شما به شما یک پاداش می‌دهد، زنگ شما به صدا درمی‌آید. نیروی کار را باز کنید و پاداش‌ها را بزنید تا آن را زیر پاداش‌های من ببینید.",
  "training.lessons.staff-your-rewards.step2": "هر پاداش کود خودش را دارد. آن را نزد خود نگه دارید — هر کسی که کود را در صندوق نشان دهد همان است که پاداش را استفاده می‌کند.",
  "training.lessons.staff-your-rewards.step3": "برای استفاده از آن، وقتی می‌خرید کود را نشان دهید. شخصی که در صندوق است آن را تایپ می‌کند و استفاده‌شده علامت می‌زند — هر کود دقیقاً یک بار کار می‌کند.",
  "training.lessons.staff-your-rewards.step4": "پاداش‌ها یک لذت پلان Business هستند. اگر دکان شما در Business نیست، زبانه پاداش‌ها به جای آن یک دروازه قفل‌شده نشان می‌دهد — آن پلان است، نه یک اشتباه.",
  "training.lessons.staff-your-rewards.title": "پاداش‌های شما: پیدا کردن کود و استفاده از آن",
  "training.module.rewards": "پاداش‌ها و انگیزه‌ها",
