  "pos.toast.help": "Toast از راه برنامه شریک Toast وصل می‌شود. وقتی اعتبارنامه‌های شریک رستوران شما آماده شد، آن‌ها را اینجا بچسبانید و هر فروش Toast اجناسش را خودش از موجودی اینجا بیرون می‌کند.",
  "pos.toast.connect": "وصل کردن Toast",
  "pos.toast.connectedToast": "Toast وصل شد. فروش‌هایش حالا اینجا حساب می‌شوند.",
  "pos.toast.clientIdPlaceholder": "شناسه مشتری از اعتبارنامه‌های شریک Toast شما",
